  _apply(event) {
    const p = event.payload;
   110|    if (event.kind === 'task.created') {
      this._tasks.set(p.id, freeze({ ...clone(p), status: 'pending', assignee: null, version: 1, createdEvent: event.seq, claimedEvent: null, terminalEvent: null, artifactIds: [] }));
